        // Let's test: suppose heal[i]=3, initial health 5 with 0 heals. Then best[5]=0. Loop h=5: nh=8, best[8]=1. Then h=8: nh=min(H,11), best[11]=2. So it works.
        // So we can use this.

        // Now after healing, we descend to next level (if i < N-1) or we are done (if i == N-1, we need to descend to treasure)
        // But we need to apply descent after healing. So for each health h in best, if h > cost[i], then we can go to level i+1 with health h - cost[i] (must be > 0).
        // For i == N-1, we don't need to go to next level, we just need to descend to treasure. So the final answer is min over h > cost[N-1] of best[h] (since we need to descend and have health > 0 after descent). Actually we need to descend, so we must have h > cost[i] and after descent health = h - cost[i] > 0. So we can compute answer directly from best at the last level.

        if (i == N-1) {
            int ans = INF;
            for (int h = cost[i]+1; h <= H; h++) {
                if (best[h] != INF) ans = min(ans, best[h]);
            }
            if (ans == INF) cout << -1 << "\n";
            else cout << ans << "\n";
            return 0;
        } else {
            // Transfer to next level
            for (int h = cost[i]+1; h <= H; h++) {
                if (best[h] == INF) continue;
                int nh = h - cost[i];
                dp[i+1][nh] = min(dp[i+1][nh], best[h]);
            }
        }
    }

    // Should not reach here
    cout << -1 << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long H;
    cin >> N >> H;

    vector<long long> d(N), h(N);
    for (int i = 0; i < N - 1; ++i) cin >> d[i];
    for (int i = 0; i < N - 1; ++i) cin >> h[i];

    const long long INF = (1LL << 60);

    // dp[i][hp] conceptually:
    // minimum number of heals used to arrive at level i with hp health.
    // We only keep current layer.
    //
    // Since H is an integer health cap, this standard DP is feasible only if H is small.
    // But the intended solution can be optimized by noticing:
    // for each number of heals, keeping maximum achievable health is enough.
    //
    // best[k] = maximum health we can have at current level after using exactly k heals.
    vector<long long> best(N + 1, -1), nxt(N + 1, -1);
    best[0] = H;

    for (int i = 0; i < N - 1; ++i) {
        fill(nxt.begin(), nxt.end(), -1);

        for (int used = 0; used <= i; ++used) {
            if (best[used] <= 0) continue;

            long long hp = best[used];

            // We may heal t times on this floor before descending.
            // After healing, health becomes min(H, hp + t*h[i]).
            // Need resulting health > d[i] to survive descent, and after descent:
            // new_hp = healed_hp - d[i].
            //
            // For fixed used+t, larger t only helps until cap H.
            // We need minimum t for each transition count, but to maximize resulting hp
            // for a given total number of heals, it's enough to consider exact t.
            //
            // Since total heals answer is at most N-1 in many practical cases? Not guaranteed.
            // However, if h[i] == 0 and hp <= d[i], impossible from this state.
            //
            // We'll try all possible additional heals up to N, which is valid because
            // we can always postpone unnecessary heals; optimal answer never needs more than N-1
            // if each needed floor can be fixed locally. To be safe, derive exact needed count.

            if (hp > d[i]) {
                nxt[used] = max(nxt[used], hp - d[i]);
            }

            if (h[i] > 0) {
                // minimum heals needed to make hp_after_heal > d[i]
                long long need = 0;
                if (hp <= d[i]) {
                    need = (d[i] + 1 - hp + h[i] - 1) / h[i];
                }

                // If even full health can't survive, impossible.
                if (H > d[i] && need <= N) {
                    long long healed = min(H, hp + need * h[i]);
                    if (healed > d[i] && used + need <= N) {
                        nxt[used + (int)need] = max(nxt[used + (int)need], healed - d[i]);
                    }
                }
            }
        }

        best.swap(nxt);
    }

    int ans = -1;
    for (int k = 0; k <= N; ++k) {
        if (best[k] >= 0) {
            ans = k;
            break;
        }
    }

    cout << ans << '\n';
    return 0;
}
